import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        int[] a = new int[p];
        int sets = 0;

        for (int i = 0; i < p; i++) {
            if (a[i] == 0) {
                sets += 1;
                int r = i;
                while (a[r] == 0) {
                    a[r] = 1;
                    r = (int)((long)r * k % p);
                }
            }
        }

        if (k == 0) {
            sets = p;
        } else if (k == 1) {
            sets = p + 1;
        }

        long res = 1;
        long big = 1000000007L;
        for (int i = 0; i < sets - 1; i++) {
            res = (res * p) % big;
        }
        System.out.println(res);
        sc.close();
    }
}
